import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
type GameMap = any; type Unit = any;

const [finalRoot, beforeRoot, resultPath] = process.argv.slice(2);
assert.ok(finalRoot && beforeRoot && resultPath, 'pass final checkout, baseline helper checkout and result JSON path');
const { createMap, createUnit } = await import(pathToFileURL(`${finalRoot}/src/shared/map.ts`).href);
async function bundle(root: string) {
  const module = (name: string) => import(pathToFileURL(`${root}/src/shared/${name}.ts`).href);
  return {
    motion: await module('ship-motion'),
    collision: await module('ship-collisions'),
    rendezvous: await module('crew-rendezvous'),
    planning: await module('ship-planning-budget'),
    defense: await module('ship-defense'),
    decks: await module('decks'),
    geometry: await module('ship-geometry'),
  };
}
const before = await bundle(beforeRoot!), after = await bundle(finalRoot!);
const terrain = { cols: 128, rows: 128, cell: 32, cells: '~'.repeat(128 * 128) };
const map: GameMap = { ...createMap('bareDuel'), width: 4096, height: 4096, terrain };
const a = createUnit('a', 'player', 'transport', 1000, 1000);
const b = createUnit('b', 'player', 'transport', 1250, 1000);
const hunter = createUnit('hunter', 'player', 'warship', 1800, 1800);
const quarry = createUnit('quarry', 'enemy', 'warship', 2250, 1800);
const crew = createUnit('crew', 'player', 'footman', 1000, 1000);
const walker = createUnit('walker', 'player', 'footman', 700, 1000);
for (const ship of [a, b, hunter, quarry]) ship.sailing = { heading: 0, speed: ship === a ? 64 : 0, load: 0, balance: 0, velocityX: ship === a ? 64 : 0, velocityY: 0 };
a.order = { type: 'move', x: 2700, y: 1000 };
quarry.order = { type: 'hold', x: quarry.x, y: quarry.y };
crew.deck = { shipId: a.id, x: -20, y: 0 };
crew.cabin = { shipId: a.id };
const yard = { id: 'dock', kind: 'shipyard', owner: 'player', x: 2000, y: 2300, radius: 32, hp: 1000, maxHp: 1000 };
let oldUnits = structuredClone([a, b, hunter, quarry, crew, walker]);
let newUnits = structuredClone(oldUnits);
const oldMap = structuredClone(map), newMap = structuredClone(map);
const oldYard = structuredClone(yard), newYard = structuredClone(yard);
const hash = createHash('sha256');
let contacts = 0, groundClips = 0, frameResets = 0;

function transition(units: Unit[], tick: number) {
  if (tick === 40) { const crew = units.find(unit => unit.id === 'crew')!; delete crew.cabin; crew.order = { type: 'board', transportId: 'b' }; }
  if (tick === 60) units.find(unit => unit.id === 'crew')!.order = { type: 'idle' };
  if (tick === 100) for (const unit of units) if (unit.sailing) unit.hp = 0;
  if (tick === 120) for (const unit of units) if (unit.sailing) unit.hp = unit.maxHp;
  if (tick === 200) { const ship = createUnit('late', 'player', 'transport', 1500, 2300); ship.sailing = { heading: 0, speed: 64, load: 0, balance: 0, velocityX: 64, velocityY: 0 }; ship.order = { type: 'move', x: 3000, y: 2300 }; units.push(ship); }
  if (tick === 400) return units.filter(unit => unit.id !== 'b');
  return units;
}

function step(mod: Awaited<ReturnType<typeof bundle>>, units: Unit[], map: GameMap, yard: typeof oldYard, tick: number) {
  if (tick === 300) yard.x -= 300;
  mod.motion.beginShipMotionFrame(units, map, [yard]);
  mod.planning.beginShipPlanningFrame(units, tick);
  mod.rendezvous.prepareCrewRendezvous(map, units);
  const holds = mod.rendezvous.boardingHoldShips(units);
  const defense = mod.defense.prepareShipDefenseFrame({ units, map, items: [], teams: { player: 'a', enemy: 'b' } }, (ship: Unit, range: number, visit: (unit: Unit) => void) => {
    for (const enemy of units) if (enemy.owner !== ship.owner && Math.hypot(enemy.x - ship.x, enemy.y - ship.y) <= range) visit(enemy);
  }, holds);
  const grants: string[] = [];
  for (const ship of units) if (ship.sailing && ship.hp > 0) {
    if (mod.planning.tryAdmitShipPlan(ship)) grants.push(ship.id);
    if (ship.id === 'b' || ship.id === 'hunter' || ship.id === 'quarry') continue;
    const yaw = tick % 40 < 20 ? .004 : -.004;
    mod.motion.advanceShip(ship, map, units, { yaw, surge: tick % 100 < 80 ? 3.2 : -1.6 });
    mod.motion.advanceShip(ship, map, units, { yaw, surge: tick % 100 < 80 ? 3.2 : -1.6 });
  }
  mod.decks.syncDecks(units);
  mod.decks.settleGangwayCrossings(units);
  const walker = units.find(unit => unit.id === 'walker')!;
  const at = mod.collision.constrainGroundShipStep(map, walker, walker, { x: 1400, y: 1000 }, units);
  const impactCount = mod.collision.shipCollisionImpactCount(units);
  const impacts = mod.collision.drainShipCollisionImpacts(units);
  return { units, map, impacts, impactCount, at, holds: [...holds], defense: [...defense], grants };
}

for (let tick = 0; tick < 600; tick++) {
  oldUnits = transition(oldUnits, tick); newUnits = transition(newUnits, tick);
  if (tick === 300) { oldUnits = JSON.parse(JSON.stringify(oldUnits)); newUnits = JSON.parse(JSON.stringify(newUnits)); }
  const old = step(before, oldUnits, oldMap, oldYard, tick), current = step(after, newUnits, newMap, newYard, tick);
  const previousJson = JSON.stringify(old), currentJson = JSON.stringify(current);
  assert.equal(currentJson, previousJson, `complete helper state differs at tick ${tick}`);
  hash.update(currentJson);
  contacts += current.impacts.length;
  if (current.at.x !== 1400) groundClips++;
  if (tick >= 100 && tick < 120) { assert.equal(current.impactCount, 0); assert.equal(current.impacts.length, 0); frameResets++; }
}
const result = { scope: '600 ticks of complete helper-observable JSON equivalence; identical map, orders, hull poses, crew, defense, saved planner tickets, impacts and direct ground queries', ticks: 600, contacts, groundClips, emptyFramesWithReset: frameResets, sha256: hash.digest('hex') };
assert.ok(contacts > 0, 'fixture must exercise real physical impacts');
writeFileSync(resultPath!, JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result));
